INSERT INTO `blogs` (`id`, `title`, `slug`, `short_des`, `description`, `meta_title`, `meta_keyword`, `meta_description`, `f_image`, `image`, `alt_name`, `publish_date`, `status`, `createdBy`, `updatedBy`, `created_at`, `updated_at`) VALUES
(1, 'Bangladesh Prepares for the 2025 Asian Para Games', 'bangladesh-prepares-for-the-2025-asian-para-games', 'NPC Bangladesh begins an intensive training program ahead of the 2025 Asian Para Games.', '<p>The National Paralympic Committee of Bangladesh has launched a nationwide talent development and\n            training program to prepare athletes for the 2025 Asian Para Games. The initiative includes\n            centralized training camps, coaching upgrades, and medical support...</p>', 'Asian Para Games 2025 Bangladesh Preparation', 'Asian Para Games, Paralympic Bangladesh, Para Sports', 'NPC Bangladesh begins preparation for the 2025 Asian Para Games with new training programs.', 'https://placehold.co/200x400?text=Paralympics', 'themes/default/assets/img/Air-Purify.png', 'Bangladesh Para Games Training', '2026-08-24 06:09:51', '1', 1, NULL, '2026-08-26 06:09:51', '2026-08-26 06:09:51'),
(2, 'Inspiring Journey of Bangladeshi Para Swimmer Mahfuzur Rahman', 'inspiring-journey-of-bangladeshi-para-swimmer-mahfuzur-rahman', 'From village ponds to international championships—Mahfuzur inspires millions.', '<p>Mahfuzur Rahman, a para swimmer from Dhaka, has overcome physical challenges and financial\n            hardship to represent Bangladesh in multiple international swimming events. His story highlights\n            resilience, dedication, and the power of inclusive sports...</p>', 'Bangladeshi Para Athlete Story', 'Para swimmer, Bangladesh athletes, Paralympics', 'The inspiring success story of Bangladeshi para swimmer Mahfuzur Rahman.', 'https://placehold.co/200x400?text=Mahfuzur', 'themes/default/assets/img/Air-Purify.png', 'Para Swimmer Mahfuzur Rahman', '2026-08-21 06:09:51', '1', 1, NULL, '2026-08-26 06:09:51', '2026-08-26 06:09:51'),
(3, 'NPC Bangladesh Launches New Athlete Talent Hunt Program', 'npc-bangladesh-launches-new-athlete-talent-hunt-program', 'A nationwide initiative to identify emerging para athletes.', '<p>To expand the future pool of competitive para athletes, NPC Bangladesh has introduced\n            a new Talent Hunt Program across 20 districts. The program aims to scout athletes with physical\n            impairments and offer structured training pathways...</p>', 'Para Athlete Talent Hunt Bangladesh', 'Talent hunt, Paralympics Bangladesh, Para athletes', 'NPC Bangladesh launches a nationwide talent hunt program for para athletes.', 'https://placehold.co/200x400?text=Training', 'themes/default/assets/img/Air-Purify.png', 'Para Athlete Talent Hunt', '2026-08-19 06:09:51', '1', 1, NULL, '2026-08-26 06:09:51', '2026-08-26 06:09:51'),
(4, 'Bangladesh Secures First Medal in World Para Athletics Grand Prix', 'bangladesh-secures-first-medal-in-world-para-athletics-grand-prix', 'A historic milestone for the nation as para athlete Raihan wins bronze.', '<p>Bangladesh celebrated a historic achievement as para athlete Md. Raihan secured a bronze\n            medal in the 400m T47 event at the World Para Athletics Grand Prix. This victory marks a major\n            step forward in the nation’s Paralympic journey...</p>', 'Bangladesh Paralympic Medal News', 'Para Athletics, Bangladesh medal, Paralympics', 'Bangladesh wins its first medal in the World Para Athletics Grand Prix.', 'https://placehold.co/200x400?text=Medal', 'themes/default/assets/img/Air-Purify.png', 'Bangladesh Para Athletics Medal', '2026-08-16 06:09:51', '1', 1, NULL, '2026-08-26 06:09:51', '2026-08-26 06:09:51'),
(5, 'International Paralympic Committee Praises Bangladesh’s Progress', 'international-paralympic-committee-praises-bangladeshs-progress', 'IPC delegation acknowledges improvements in training, governance, and inclusion.', '<p>A recent visit by the International Paralympic Committee (IPC) praised the rapid\n            development of para sports in Bangladesh. The delegation highlighted advancements in athlete\n            classification, facility upgrades, and digital governance...</p>', 'IPC visit to Bangladesh', 'IPC, Paralympics, Bangladesh progress', 'International Paralympic Committee praises Bangladesh for progress.', 'https://placehold.co/200x400?text=IPC', 'themes/default/assets/img/Air-Purify.png', 'IPC Visit Bangladesh', '2026-08-14 06:09:51', '1', 1, NULL, '2026-08-26 06:09:51', '2026-08-26 06:09:51');
