(1, 'Products', 'products', 'Explore high-performance air purification systems, smart sensors, protective masks, accessories, and replacement parts.', '[{\"desc\": \"Engineered for seamless installation and filter maintenance.\", \"icon\": \"bi-box-seam\", \"title\": \"Modular Design\"}, {\"desc\": \"Hospital-grade certified particulate containment.\", \"icon\": \"bi-shield-check\", \"title\": \"Medical H13/H14 HEPA\"}, {\"desc\": \"Real-time air analytics and auto-speed regulation.\", \"icon\": \"bi-cpu\", \"title\": \"IoT Smart Sensors\"}, {\"desc\": \"Tested and certified by international IAQ standards.\", \"icon\": \"bi-award\", \"title\": \"Industry Certified\"}]', 1, NULL, NULL, NULL, 'bi bi-box-seam', NULL, 'themes/default/assets/img/Air-Purify.png', NULL, '#00c853', 1, 1, 0, 1, 1, NULL, NULL, NULL, '2026-08-28 22:53:51', '2026-08-28 22:53:54'),
(2, 'Fresh Air Systems', 'fresh-air-systems', 'Industrial and residential fresh air exchange systems for continuous ventilation.', '[{\"desc\": \"Captures 99.97% of airborne pollutants.\", \"icon\": \"bi-shield-check\", \"title\": \"Advanced Filtration\"}, {\"desc\": \"Engineered for minimum power consumption.\", \"icon\": \"bi-lightning-charge\", \"title\": \"Energy Efficient\"}, {\"desc\": \"Adaptive air purification and IoT monitoring.\", \"icon\": \"bi-cpu\", \"title\": \"Smart Automation\"}, {\"desc\": \"Engineered to highest international standards.\", \"icon\": \"bi-award\", \"title\": \"Certified Quality\"}]', 1, NULL, NULL, NULL, 'bi bi-wind', NULL, NULL, NULL, '#0066cc', 1, 1, 0, 1, 1, NULL, NULL, 1, '2026-08-28 22:53:51', '2026-08-28 22:53:54'),
(3, 'Home Fresh Air Systems', 'home-fresh-air-systems', 'Advanced home ventilation systems providing continuous fresh, clean air.', '[{\"desc\": \"Captures 99.97% of airborne pollutants.\", \"icon\": \"bi-shield-check\", \"title\": \"Advanced Filtration\"}, {\"desc\": \"Engineered for minimum power consumption.\", \"icon\": \"bi-lightning-charge\", \"title\": \"Energy Efficient\"}, {\"desc\": \"Adaptive air purification and IoT monitoring.\", \"icon\": \"bi-cpu\", \"title\": \"Smart Automation\"}, {\"desc\": \"Engineered to highest international standards.\", \"icon\": \"bi-award\", \"title\": \"Certified Quality\"}]', 1, NULL, NULL, NULL, 'bi bi-house-door', NULL, 'product-categories/3/prodcat_6aaa673ff2c45.jpg', 'Home Fresh Air Systems', '#0066cc', 1, 1, 0, 1, 1, NULL, 2, 2, '2026-08-28 22:53:51', '2026-09-16 03:54:08'),
(5, 'Industrial Fresh Air Systems', 'industrial-fresh-air-systems', 'Heavy-duty ventilation units engineered for factories and manufacturing facilities.', '[{\"desc\": \"Captures welding fumes, solvents, and chemical vapors.\", \"icon\": \"bi-cone-striped\", \"title\": \"Heavy Fume Capture\"}, {\"desc\": \"Guarantees permissible exposure limit adherence.\", \"icon\": \"bi-shield-exclamation\", \"title\": \"OSHA Compliance\"}, {\"desc\": \"Robust metal chassis built for harsh environments.\", \"icon\": \"bi-gear-wide-connected\", \"title\": \"Continuous 24/7 Duty\"}, {\"desc\": \"Massive CFM airflow for expansive factory floors.\", \"icon\": \"bi-funnel-fill\", \"title\": \"High Airflow CADR\"}]', 1, NULL, NULL, NULL, 'bi bi-gear-wide-connected', NULL, 'product-categories/5/prodcat_6aaa677e96f04.jpg', 'Industrial Fresh Air Systems', '#0066cc', 1, 1, 0, 3, 1, NULL, 2, 2, '2026-08-28 22:53:51', '2026-09-16 03:55:10'),
(6, 'Air Purifiers', 'air-purifiers', 'State-of-the-art air purifiers featuring True HEPA H13 filtration.', '[{\"desc\": \"Captures 99.97% of airborne pollutants.\", \"icon\": \"bi-shield-check\", \"title\": \"Advanced Filtration\"}, {\"desc\": \"Engineered for minimum power consumption.\", \"icon\": \"bi-lightning-charge\", \"title\": \"Energy Efficient\"}, {\"desc\": \"Adaptive air purification and IoT monitoring.\", \"icon\": \"bi-cpu\", \"title\": \"Smart Automation\"}, {\"desc\": \"Engineered to highest international standards.\", \"icon\": \"bi-award\", \"title\": \"Certified Quality\"}]', 1, NULL, NULL, NULL, 'bi bi-funnel', NULL, NULL, NULL, '#00c853', 1, 1, 0, 2, 1, NULL, NULL, 1, '2026-08-28 22:53:51', '2026-08-28 22:53:55'),
(7, 'Air Purifiers for Home', 'air-purifiers-for-home', 'Compact and powerful room purifiers designed for quiet residential use.', '[{\"desc\": \"Captures 99.97% of airborne pollutants.\", \"icon\": \"bi-shield-check\", \"title\": \"Advanced Filtration\"}, {\"desc\": \"Engineered for minimum power consumption.\", \"icon\": \"bi-lightning-charge\", \"title\": \"Energy Efficient\"}, {\"desc\": \"Adaptive air purification and IoT monitoring.\", \"icon\": \"bi-cpu\", \"title\": \"Smart Automation\"}, {\"desc\": \"Engineered to highest international standards.\", \"icon\": \"bi-award\", \"title\": \"Certified Quality\"}]', 1, NULL, NULL, NULL, 'bi bi-house-heart', NULL, 'product-categories/7/prodcat_6aaa67a9bd8d5.jpg', 'Air Purifiers for Home', '#0066cc', 1, 1, 0, 1, 1, NULL, 2, 6, '2026-08-28 22:53:51', '2026-09-16 03:55:53'),
(8, 'Air Purifiers for Commercial', 'air-purifiers-for-commercial', 'High CADR air purification units for lobbies, conference rooms, and open offices.', '[{\"desc\": \"Higher oxygen levels increase focus and reduce fatigue.\", \"icon\": \"bi-building\", \"title\": \"Productivity Boost\"}, {\"desc\": \"Fewer sick days and higher workplace satisfaction.\", \"icon\": \"bi-people\", \"title\": \"Occupant Wellness\"}, {\"desc\": \"Demand-controlled ventilation lowers HVAC load.\", \"icon\": \"bi-lightning-charge\", \"title\": \"Energy Efficient\"}, {\"desc\": \"Enterprise management across multi-story facilities.\", \"icon\": \"bi-diagram-3\", \"title\": \"Central BMS Sync\"}]', 1, NULL, NULL, NULL, 'bi bi-briefcase', NULL, 'product-categories/8/prodcat_6aaa67cbc256f.jpg', 'Air Purifiers for Commercial', '#7c3aed', 1, 1, 0, 2, 1, NULL, 2, 6, '2026-08-28 22:53:51', '2026-09-16 03:56:27'),
(9, 'Air Purifiers for Healthcare', 'air-purifiers-for-healthcare', 'Medical-grade air purifiers engineered for clinics, ICUs, and patient rooms.', '[{\"desc\": \"Captures 99.97% of harmful airborne micro-particles.\", \"icon\": \"bi-shield-check\", \"title\": \"PM2.5 Capture\"}, {\"desc\": \"Eliminates pollen, dust mites, and pet dander.\", \"icon\": \"bi-flower1\", \"title\": \"Allergen Reduction\"}, {\"desc\": \"Maintains optimal oxygen levels for peak wellness.\", \"icon\": \"bi-cloud\", \"title\": \"CO2 & O2 Balance\"}, {\"desc\": \"Guarantees continuous 100% fresh air circulation.\", \"icon\": \"bi-wind\", \"title\": \"Continuous Fresh Air\"}]', 1, NULL, NULL, NULL, 'bi bi-hospital', NULL, 'product-categories/9/prodcat_6aaa68597aa4f.jpg', 'Air Purifiers for Healthcare', '#00c853', 1, 1, 0, 3, 1, NULL, 2, 6, '2026-08-28 22:53:51', '2026-09-16 03:58:49'),
(10, 'Monitoring & Sensors', 'monitoring-sensors', 'Real-time air quality monitors and environmental sensors.', '[{\"desc\": \"Continuous high-frequency tracking of 9 critical IAQ parameters.\", \"icon\": \"bi-display\", \"title\": \"Live Telemetry\"}, {\"desc\": \"Instant escalation notifications when pollutant levels spike.\", \"icon\": \"bi-bell\", \"title\": \"Instant Alerts\"}, {\"desc\": \"One-click automated ESG and regulatory compliance reporting.\", \"icon\": \"bi-file-earmark-pdf\", \"title\": \"Audit-Ready Reports\"}, {\"desc\": \"Unified global facility air intelligence from one console.\", \"icon\": \"bi-buildings\", \"title\": \"Enterprise Multi-Site\"}]', 1, NULL, NULL, NULL, 'bi bi-broadcast', NULL, NULL, NULL, '#06b6d4', 1, 1, 0, 3, 1, NULL, NULL, 1, '2026-08-28 22:53:51', '2026-08-28 22:53:55'),
(11, 'Indoor Air Quality Sensors', 'indoor-air-quality-sensors', 'Precision PM2.5, VOC, CO2, and humidity sensors for continuous monitoring.', '[{\"desc\": \"Captures 99.97% of airborne pollutants.\", \"icon\": \"bi-shield-check\", \"title\": \"Advanced Filtration\"}, {\"desc\": \"Engineered for minimum power consumption.\", \"icon\": \"bi-lightning-charge\", \"title\": \"Energy Efficient\"}, {\"desc\": \"Adaptive air purification and IoT monitoring.\", \"icon\": \"bi-cpu\", \"title\": \"Smart Automation\"}, {\"desc\": \"Engineered to highest international standards.\", \"icon\": \"bi-award\", \"title\": \"Certified Quality\"}]', 1, NULL, NULL, NULL, 'bi bi-activity', NULL, 'product-categories/11/prodcat_6aaa688718a03.jpg', 'Indoor Air Quality Sensors', '#06b6d4', 1, 1, 0, 1, 1, NULL, 2, 10, '2026-08-28 22:53:52', '2026-09-16 03:59:35'),
(12, 'AIRE Dashboard Platform', 'aire-dashboard-platform', 'Centralized IoT cloud dashboard for real-time facility air metrics and analytics.', '[{\"desc\": \"Captures 99.97% of airborne pollutants.\", \"icon\": \"bi-shield-check\", \"title\": \"Advanced Filtration\"}, {\"desc\": \"Engineered for minimum power consumption.\", \"icon\": \"bi-lightning-charge\", \"title\": \"Energy Efficient\"}, {\"desc\": \"Adaptive air purification and IoT monitoring.\", \"icon\": \"bi-cpu\", \"title\": \"Smart Automation\"}, {\"desc\": \"Engineered to highest international standards.\", \"icon\": \"bi-award\", \"title\": \"Certified Quality\"}]', 1, NULL, NULL, NULL, 'bi bi-display', NULL, 'product-categories/12/prodcat_6aaa68a5672eb.jpg', 'AIRE Dashboard Platform', '#00c853', 1, 1, 0, 2, 1, NULL, 2, 10, '2026-08-28 22:53:52', '2026-09-16 04:00:05'),
(13, 'Protective Masks', 'protective-masks', 'Active wearable masks and certified particulate respirators.', '[{\"desc\": \"Captures 99.97% of airborne pollutants.\", \"icon\": \"bi-shield-check\", \"title\": \"Advanced Filtration\"}, {\"desc\": \"Engineered for minimum power consumption.\", \"icon\": \"bi-lightning-charge\", \"title\": \"Energy Efficient\"}, {\"desc\": \"Adaptive air purification and IoT monitoring.\", \"icon\": \"bi-cpu\", \"title\": \"Smart Automation\"}, {\"desc\": \"Engineered to highest international standards.\", \"icon\": \"bi-award\", \"title\": \"Certified Quality\"}]', 1, NULL, NULL, NULL, 'bi bi-mask', NULL, NULL, NULL, '#00c853', 1, 1, 0, 4, 1, NULL, NULL, 1, '2026-08-28 22:53:52', '2026-08-28 22:53:55'),
