INSERT INTO `product_descriptions` (`id`, `product_id`, `description`, `tag`, `meta_title`, `meta_description`, `meta_keyword`, `description_image`, `documentation_pdf`, `safety_pdf`, `instructions_pdf`, `video`, `specs_badge`, `specs_title`, `specs_description`, `specs_image`, `spec1_icon`, `spec1_badge`, `spec1_value`, `spec1_unit`, `spec1_desc`, `spec2_icon`, `spec2_badge`, `spec2_value`, `spec2_unit`, `spec2_desc`, `spec3_icon`, `spec3_badge`, `spec3_value`, `spec3_unit`, `spec3_desc`, `spec4_icon`, `spec4_badge`, `spec4_value`, `spec4_unit`, `spec4_desc`, `features_badge`, `features_title`, `features_description`, `features_image`, `feature1_icon`, `feature1_title`, `feature1_desc`, `feature2_icon`, `feature2_title`, `feature2_desc`, `feature3_icon`, `feature3_title`, `feature3_desc`, `applications_title`, `applications_description`, `technology_badge`, `technology_title`, `technology_description`, `technology_image`, `technology_card_title`, `technology_card_description`, `tech_feature1_title`, `tech_feature1_desc`, `tech_feature2_title`, `tech_feature2_desc`, `tech_feature3_title`, `tech_feature3_desc`, `created_at`, `updated_at`) VALUES
(1, 1, 'BROAD FF100 is a compact wall-mounted, dual-flow, single-room fresh-air system positioned by BROAD as an energy-recovery ventilator (ERV). It delivers 100 m³/h of outdoor air, filters incoming particulate matter, and exhausts stale indoor air through a separate airflow path. Its energy-recovery core transfers part of the temperature difference between incoming and outgoing air without mixing the two air streams.', 'HVAC IN-DUCT PURIFICATION', 'BROAD FE6 AirPro Fresh', 'BROAD FE6 AirPro Fresh', 'AIRPRO Allergies&Dust Asthma Fresh Air Unit Heat Recovery HEPA Filter HOME Mold&Fog Window Pets & Odor Room_200~450 sqft', NULL, NULL, NULL, NULL, NULL, 'SPECIFICATIONS', 'Technical Specifications', 'Laboratory-validated performance metrics and component architecture for the AIRE Products Pro S8 System.', 'product/1/specs-bg-1792709171.png', 'bi bi-shield-check', 'Voltage', '110–220', 'V', NULL, 'bi bi-wind', 'Rated power', '5–31', 'W', NULL, 'bi bi-battery-charging', 'Room area', '200-450', 'SFT', NULL, 'bi bi-box-seam', 'Weight', '9.98', 'kg', NULL, 'FEATURES', 'Advanced Fresh-Air Technology', 'Experience a smarter approach to indoor ventilation with BROAD FE6 AirPro Fresh. Combining filtered outdoor air, high-efficiency PM2.5 filtration and heat recovery, it helps create a cleaner and more comfortable indoor environment.', 'product/1/feat-bg-1793130043.avif', 'bi bi-shield-lock', '100% Fresh Outdoor Air', 'Fresh outdoor air ventilation helps renew indoor air without relying on a mixed recycled-air supply.', 'bi bi-lightbulb', '99% PM2.5 Filtration', 'Advanced filtration designed to remove up to 99% of PM2.5 fine particles, helping reduce airborne particulate pollution in your indoor space.', 'bi bi-funnel', '60% Heat Recovery Efficiency', 'Heat recovery transfers part of the temperature difference between incoming and outgoing air, helping maintain indoor comfort while reducing ventilation-related energy loss.', 'Fresh Air for Everyday Living', 'Designed for bedrooms, home offices and modern apartments, BROAD FE6 delivers filtered fresh air with efficient heat recovery in a compact, wall-mounted design.', 'TECHNOLOGY', 'The Technology of  FF100', 'FF100 uses a balanced, dual-flow ventilation concept. Outdoor air is drawn into the unit, passes through the coarse and high-efficiency filtration stages, and is supplied indoors. At the same time, stale indoor air is exhausted through a separate path. The two air streams pass through an energy-recovery heat-exchange core so temperature energy can be transferred while the air streams remain separated.', 'product/1/tech_1790144812.jpeg', 'Outdoor air intake', 'Brings outdoor air toward the filtration section', 'Coarse filter', 'Captures larger dust and protects the high-efficiency filter', 'HEPA filter', 'Captures fine particulate matter in incoming air', 'Heat exchanger', 'Transfers sensible heat between incoming and outgoing air streams', '2026-08-26 06:09:55', '2026-10-27 13:40:43'),
(4, 4, 'The AIRE Fresh Air Systems Ultra Series 803 represents advanced engineering in clean air management. Built for demanding technical, commercial, and luxury residential environments, delivering certified particulate capture, ultra-quiet fluid dynamics, and intelligent automation.', 'CLEANROOM GRADE SYSTEM', 'AIRE Fresh Air Systems Ultra Series 803 | AIRE Advanced Clean Air Systems', 'Explore AIRE Fresh Air Systems Ultra Series 803. Certified medical-grade H13/H14 HEPA filtration, smart IoT sensor array, and architectural performance.', 'aire, fresh-air-systems, air purifier, clean air, hepa filter, h13, h14', NULL, NULL, NULL, NULL, NULL, 'SPECIFICATIONS', 'Technical Specifications', 'Laboratory-validated performance metrics and component architecture for the AIRE Fresh Air Systems Ultra Series 803 System.', 'products/specifications.png', 'bi bi-shield-check', 'FILTRATION', '99.97%', '', '@ 0.3MM EFFICIENCY', 'bi bi-wind', 'VELOCITY', '4.2', 'L/sec', 'MAX AIRFLOW RATE', 'bi bi-battery-charging', 'ENDURANCE', '12', 'Hours', 'CONTINUOUS OPERATION', 'bi bi-box-seam', 'MASS', '185', 'Grams', 'TOTAL SYSTEM WEIGHT', 'FEATURES', 'Precision Engineered Details', 'The AIRE Fresh Air Systems Ultra Series 803 is a masterclass in industrial design, where every component is optimized for performance, durability, and user comfort.', 'products/features.png', 'bi bi-shield-lock', 'Medical-Grade Facial Seal', 'Hypoallergenic LSR silicone ensures a perfect, pressure-mapped seal for all-day comfort in high-stakes environments.', 'bi bi-lightbulb', 'Active Feedback Ring', 'Integrated LED halo provides real-time data on air quality and filter life at a glance, ensuring constant operational awareness.', 'bi bi-funnel', 'Advanced HEPA Filtration', 'Dual H13 Industrial filters capture 99.97% of particulates with micro-pleated geometry for maximum surface area efficiency.', 'Industrial Excellence, Personal Comfort', 'AIRE Fresh Air Systems Ultra Series 803 is engineered to exceed safety standards in the most demanding environments, from high-tech labs to daily mobility.', 'TECHNOLOGY', 'The Physics of Pure Air', 'Beyond simple filtration, the AIRE Fresh Air Systems Ultra Series 803 utilizes fluid dynamics and active sensor arrays to maintain a stable positive-pressure environment within the mask, preventing untreated air ingress.', 'products/airpro_mask_fb2.png', 'ACTIVE POSITIVE PRESSURE', 'Smart sensors detect inhalation resistance and automatically adjust fan velocity to ensure a constant supply of fresh air, regardless of respiratory demand.', 'TURBULENT FLOW CONTROL', 'Internal ducting is modeled using computational fluid dynamics to minimize air turbulence and operational noise below 20dB.', 'PARTICULATE SENSING', 'Integrated laser-based sensors scan for PM2.5 concentrations every 500ms, providing hyper-responsive airflow modulation.', 'BIO-MECHANICAL FIT', 'The structural chassis is crafted from aerospace-grade polymers, achieving an industry-leading strength-to-weight ratio for ergonomic balance.', '2026-08-26 06:09:56', '2026-08-26 06:10:20'),
