INSERT INTO `sections` (`id`, `name`, `data`, `createdBy`, `updatedBy`, `created_at`, `updated_at`) VALUES
(1, 'about_vision', '{\"image\": \"themes/default/assets/img/Air-Purify.png\", \"title\": \"Vision\", \"status\": \"1\", \"content\": \"<p>Through its programs and events, the NPCB’s vision is to foster a truly inclusive Bangladesh, where Para athletes have equal opportunities to participate in sports at all levels and are recognized for their successes.</p>\", \"home_content\": null}', NULL, 1, '2026-08-26 06:09:52', '2026-09-09 21:59:55'),
(2, 'about_mission_vision', '{\"quote\": \"Clean air empowers people, strengthens communities and builds a brighter tomorrow.\", \"title\": \"Mission & Vision\", \"number\": 2, \"values\": [{\"desc\": \"We put the health and wellbeing of people at the heart of our work.\", \"icon\": \"bi bi-heart\", \"title\": \"People First\"}, {\"desc\": \"We continuously push the boundaries of clean air technology.\", \"icon\": \"bi bi-lightbulb\", \"title\": \"Innovation Always\"}, {\"desc\": \"We are committed to a more sustainable and resilient future.\", \"icon\": \"bi bi-globe-americas\", \"title\": \"A Healthier Planet\"}, {\"desc\": \"We collaborate with partners and communities to create lasting impact.\", \"icon\": \"bi bi-people-fill\", \"title\": \"Stronger Together\"}], \"subtitle\": \"Our purpose, values and commitment to a better future.\", \"quote_brand\": \"CLEANER AIR\\nBRIGHTER SPACES\\nA HEALTHIER TOMORROW\", \"vision_desc\": \"A world where everyone, everywhere can breathe clean, safe and healthy air — today and for future generations.\", \"mission_desc\": \"To develop and deliver innovative, reliable and energy-efficient air solutions that create healthier indoor environments for people everywhere.\", \"purpose_desc\": \"We believe clean air is a fundamental right for everyone. Our mission and vision guide everything we do — from the technologies we develop to the communities we serve.\", \"vision_title\": \"Our Vision\", \"mission_title\": \"Our Mission\", \"purpose_badge\": \"CLEANER AIR\\nBRIGHTER SPACES\\nA HEALTHIER TOMORROW\", \"purpose_image\": \"themes/default/assets/img/about/earth_purpose.jpg\", \"purpose_title\": \"Our Purpose\"}', NULL, NULL, '2026-08-26 06:09:52', '2026-10-06 04:20:13'),
(3, 'about_mission', '{\"image\": \"themes/default/assets/img/Air-Purify.png\", \"title\": \"Mission\", \"content\": \"<ul class=\\\" ps-3 \\\">\\n                        <li class=\\\"text-dark-emphasis content-text mb-4\\\">Supporting members and providing platforms\\n                            for Para athletes to achieve their best in\\n                            sports, from national competitions to the Paralympic Games.</li>\\n                        <li class=\\\"text-dark-emphasis content-text mb-4\\\">Using sports as a tool for social and\\n                            cultural development, fostering hope, independence,\\n                            and showing that \\\"disability is not inability</li>\\n                        <li class=\\\"text-dark-emphasis content-text mb-4\\\">Leading the development of various Para\\n                            sports and helping to train coaches and\\n                            administrators</li>\\n                        <li class=\\\"text-dark-emphasis content-text mb-4\\\">Ensuring the observance of the International\\n                            Paralympic Committee\'s rules and regulations\\n                            within Bangladesh</li>\\n                    </ul>\"}', NULL, NULL, '2026-08-26 06:09:52', '2026-09-09 03:47:33'),
(4, 'history_history', '{\"image\": \"themes/default/assets/img/Air-Purify.png\", \"title\": \"History\", \"content\": \" <p class=\\\"content-text text-white opacity-75\\\">The history of the National Paralympic Committee of Bangladesh (NPCB) was formed in 1981. Bangladesh\'s debut at the Summer Paralympics was in 2004, where it sent one athlete to compete in athletics. The NPCB was formally established in 2004 and became the official national organization for para-sports, affiliated with the International Paralympic Committee (IPC). The country has since participated in every Summer Paralympics, though it has yet to win a medal.</p>\\n                    <ul class=\\\" ps-3 text-white opacity-75 content-tex\\\">\\n                        <li class=\\\" t mb-4\\\"><strong>2004: </strong>Bangladesh makes its first appearance at the 2004 Athens Summer Paralympics, sending a single athlete to compete in the men\'s 400m T46 event.</li>\\n\\n                        <li class=\\\"mb-4\\\"><strong>2004: </strong>The National Paralympic Committee of Bangladesh is officially established.</li>\\n\\n                        <li class=\\\"mb-4\\\"><strong>2008: </strong>Abdul Quader Suman represents Bangladesh at the Beijing Paralympics, competing in the men\'s 100m T12.</li>\\n\\n                        <li class=\\\"mb-4\\\"><strong>2012-2024: </strong>Bangladesh continues its participation in the Summer Paralympics.</li>\\n\\n                        <li class=\\\"mb-4\\\"><strong>2022: </strong> NPCB is granted provisional membership status by the International Paralympic Committee (IPC)..</li>\\n                        <li class=\\\"mb-4\\\"><strong>Present: </strong> The organization continues its work as a para-athlete-centered, non-profit national organization based in Dhaka.</li>\\n                </ul>\"}', NULL, NULL, '2026-08-26 06:09:52', '2026-09-09 03:47:33'),
(5, 'trust_badges', '{\"badges\": [{\"icon\": \"bi-shield-check\", \"title\": \"SECURE PAYMENTS\", \"description\": \"100% secure and encrypted payments.\"}, {\"icon\": \"bi-box-seam\", \"title\": \"FREE SHIPPING\", \"description\": \"On all orders over $150.\"}, {\"icon\": \"bi-arrow-repeat\", \"title\": \"30-DAY RETURNS\", \"description\": \"Return or exchange within 30 days.\"}, {\"icon\": \"bi-award\", \"title\": \"1 YEAR WARRANTY\", \"description\": \"Full protection and quality assurance.\"}, {\"icon\": \"bi-headset\", \"title\": \"DEDICATED SUPPORT\", \"description\": \"Expert assistance whenever you need it.\"}]}', NULL, NULL, '2026-08-26 06:09:52', '2026-08-26 06:09:52'),
(6, 'why_choose_aire', '{\"cards\": [{\"dots\": \"•••\", \"theme\": \"dark\", \"title\": \"Unmatched <br> Filtration Precision\", \"content\": \"We utilize medical-grade HEPA-14 filters combined with advanced activated carbon matrices to capture particles as small as 0.1 microns, ensuring absolute purity.\"}, {\"dots\": \"••••\", \"theme\": \"light\", \"title\": \"Smart IoT <br> Ecosystem Integration\", \"content\": \"Monitor indoor air quality in real-time, adjust fan speeds automatically based on atmospheric sensors, and track filter degradation through the AIRE mobile app.\"}, {\"dots\": \"•••••\", \"theme\": \"light\", \"title\": \"Whisper-Quiet <br> Acoustic Engineering\", \"content\": \"Architected using aerodynamic fluid dynamics to operate at ultra-low decibel levels, guaranteeing your professional or living space remains undisturbed.\"}, {\"dots\": \"••••••\", \"theme\": \"light\", \"title\": \"Sustainable & <br> Energy Efficient\", \"content\": \"Constructed with eco-conscious materials and engineered to consume minimal energy while delivering maximum Clean Air Delivery Rate (CADR).\"}], \"title\": \"Why Choose AIRE?\", \"subtitle\": \"The ultimate protocol for atmospheric purity and environmental control.\"}', NULL, NULL, '2026-08-26 22:12:52', '2026-10-06 04:20:13'),
(7, 'client_testimonials', '{\"items\": [{\"name\": \"Sarah Jenkins\", \"role\": \"INTERIOR ARCHITECT\", \"quote\": \"The AIRE Pro S1 is not just an air purifier; it\'s a piece of architectural art that has transformed our living environment.\", \"avatar\": \"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=120&q=80\", \"rating\": 5}, {\"name\": \"Marcus Chen\", \"role\": \"SENIOR FACILITY MANAGER\", \"quote\": \"Unmatched technical precision. The IAQ data reporting is exactly what our facility management team needed for ESG compliance.\", \"avatar\": \"https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=120&q=80\", \"rating\": 5}, {\"name\": \"Dr. Elena Rostova\", \"role\": \"CLINICAL ALLERGIST\", \"quote\": \"The multi-stage filtration system drastically reduced particulate matter in our high-traffic clinic rooms. Absolutely vital for our patients.\", \"avatar\": \"https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=120&q=80\", \"rating\": 5}, {\"name\": \"David Sterling\", \"role\": \"SUSTAINABILITY DIRECTOR\", \"quote\": \"Combining whisper-quiet acoustics with verifiable CADR performance has made AIRE our go-to partner for premium commercial builds.\", \"avatar\": \"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=120&q=80\", \"rating\": 5}], \"title\": \"Purity in Practice\", \"subtitle\": \"CLIENT TESTIMONIALS\"}', NULL, 1, '2026-08-29 23:29:50', '2026-10-06 04:20:13'),
(8, 'home_benefits', '{\"badge\": \"BENEFITS\", \"cards\": [{\"title\": \"Authentic Products\", \"description\": \"100% genuine guaranteed with official manufacturer warranty\"}, {\"title\": \"Warranty Coverage\", \"description\": \"Comprehensive protection and technical maintenance plan\"}, {\"title\": \"Fast Delivery\", \"description\": \"Swift nationwide door-to-door shipping service available\"}, {\"title\": \"Trusted Service\", \"description\": \"Dedicated local experts for support, setup, and advice\"}, {\"title\": \"Easy Replacement\", \"description\": \"Hassle-free filter and parts replacement availability\"}, {\"title\": \"Multiple Choices\", \"description\": \"Wide range of models and features to suit lifestyles\"}], \"image\": \"themes/default/assets/img/benifits-bg.png\", \"title\": \"Pure Air, Healthy Living\", \"subtitle\": \"Get authentic products, fast delivery, and trusted local service — only from us.\"}', NULL, 1, '2026-09-08 00:16:27', '2026-10-06 04:20:13'),
(9, 'home_lifestyle', '{\"badge\": \"LIFESTYLE\", \"items\": [{\"image\": \"home/lifestyle/s1.png\", \"title\": \"Bedroom Serenity\", \"description\": \"Sleep peacefully with cleaner air by your side. Wake up refreshed every morning with purified air.\"}, {\"image\": \"home/lifestyle/s2.png\", \"title\": \"Living Room Comfort\", \"description\": \"Enjoy family moments in a healthier environment. Keep your living space fresh and welcoming.\"}, {\"image\": \"home/lifestyle/s3.png\", \"title\": \"Office Focus\", \"description\": \"Boost productivity with fresh, purified air at work. Stay sharp and energized throughout the day.\"}, {\"image\": \"home/lifestyle/s4.png\", \"title\": \"Kids\' Room Safety\", \"description\": \"Protect your children from dust, pollen, and allergens. Ensure safe, clean air to breathe.\"}], \"title\": \"Seamless Living, Cleaner Air\", \"subtitle\": \"From bedrooms to offices, our purifiers blend effortlessly into every space while keeping your air fresh and healthy.\"}', NULL, NULL, '2026-09-08 00:22:27', '2026-10-06 04:20:13'),
(10, 'home_faq', '{\"badge\": \"SUPPORT\", \"items\": [{\"answer\": \"Under normal conditions, filters should be replaced every 120-150 hours of active use. The integrated sensor will notify you via the LED ring and app when replacement is required.\", \"question\": \"How long do the HEPA H13 filters last?\"}, {\"answer\": \"Yes. The active pressure balance system dynamically adjusts airflow to match your breathing rate, preventing CO2 buildup and keeping the interior cool during physical exertion.\", \"question\": \"Is the Airpro Mask FB2 suitable for high-intensity exercise?\"}, {\"answer\": \"The medical-grade silicone seal is detachable and can be cleaned with warm soapy water or alcohol-based wipes. Ensure the electronic chassis is removed before cleaning.\", \"question\": \"How do I sanitize the mask?\"}, {\"answer\": \"Yes, it connects to the AIRE app via Bluetooth 5.2 for real-time air quality monitoring, filter healthtracking, and firmware updates.\", \"question\": \"Does the mask support Bluetooth connectivity?\"}, {\"answer\": \"The internal battery provides up to 12 hours of continuous operation on a single charge. It supports fast charging via USB-C, reaching 80% in just 45 minutes.\", \"question\": \"What is the battery life of the active sensors?\"}], \"title\": \"Frequently Asked Questions\", \"subtitle\": \"Have questions? Here are answers to common questions about our purifiers, filters, and technology.\"}', NULL, 1, '2026-09-08 04:30:13', '2026-10-06 04:20:13'),
(11, 'home_video', '{\"image\": \"home/video_thumb.png\", \"title\": \"AIRE Pro S1 — Engineering Architecture & Air Purification\", \"video_url\": \"storage/home/home-video.mp4\", \"video_file\": \"\"}', NULL, 1, '2026-09-08 05:51:01', '2026-10-07 04:20:09'),
