(15, 'home_living_hero', '{\"badge\": \"INNOVATION\", \"image\": \"themes/default/assets/img/background-without-product.png\", \"title\": \"Home Living Hero\", \"enabled\": 1, \"subtitle\": \"Engineered for complete atmospheric transformation. Seamlessly integrates into modern living spaces with intelligent active air purification.\", \"product_id\": 33, \"button_text\": \"Buy Now\", \"description\": \"Engineered for complete atmospheric transformation. Seamlessly integrates into modern living spaces with intelligent active air purification.\"}', NULL, 1, '2026-09-09 23:39:44', '2026-10-07 03:52:17'),
(16, 'about_hero', '{\"badge\": \"OUR STORY\", \"title\": \"A Cleaner Tomorrow Starts Here \", \"subtitle\": \"From a simple idea to a global mission, our journey has always been about one thing — cleaner air for healthier, happier lives.\\n\"}', NULL, 1, '2026-10-06 04:20:13', '2026-10-07 00:35:29'),
(17, 'about_story', '{\"quote\": \"Real change happens when cleaner air becomes a right for everyone, not a privilege for a few.\", \"stats\": [{\"desc\": \"Our solutions are trusted in over 100 countries worldwide.\", \"icon\": \"bi bi-globe\", \"title\": \"100+ Countries\"}, {\"desc\": \"Cleaner, safer indoor air for families around the world.\", \"icon\": \"bi bi-house-door\", \"title\": \"Millions Healthier Homes\"}, {\"desc\": \"From offices to factories, we help organisations create healthier workplaces.\", \"icon\": \"bi bi-buildings\", \"title\": \"Thousands Businesses\"}, {\"desc\": \"Reducing emissions and supporting a more sustainable planet.\", \"icon\": \"bi bi-tree\", \"title\": \"A Cleaner Tomorrow\"}], \"title\": \"Our Journey\", \"number\": 1, \"subtitle\": \"Discover the key milestones that have shaped AIRE into a global leader in clean air solutions.\", \"hero_desc\": \"Since our founding, AIRE has been at the forefront of clean air innovation. What began as a vision to improve indoor air quality has grown into a global movement, trusted in homes, businesses and public spaces worldwide.\", \"hero_badge\": \"CLEANER AIR\\nBRIGHTER SPACES\\nA HEALTHIER TOMORROW\", \"hero_image\": \"themes/default/assets/img/about/mountains.jpg\", \"hero_title\": \"Our Journey\", \"milestones\": [{\"desc\": \"AIRE was founded with a vision to develop advanced air purification technologies for healthier indoor environments.\", \"year\": \"1988\", \"title\": \"The Beginning\"}, {\"desc\": \"We established our first R&D centre, focusing on innovative air treatment technologies and energy-efficient solutions.\", \"year\": \"1995\", \"title\": \"Research & Development\"}, {\"desc\": \"We expanded our product portfolio and entered international markets across Europe and Asia.\", \"year\": \"2005\", \"title\": \"Expanding Globally\"}, {\"desc\": \"We introduced commercial and industrial solutions, addressing air quality challenges across multiple industries, from residential to large-scale commercial projects.\", \"year\": \"2015\", \"title\": \"A Broader Impact\"}, {\"desc\": \"Our technologies are trusted in over 100 countries, improving the lives of millions through cleaner, safer air.\", \"year\": \"2020\", \"title\": \"Building Healthier Communities\"}, {\"desc\": \"We continue to innovate for a healthier planet, with a commitment to sustainability and a future where everyone can breathe better, everywhere.\", \"year\": \"Today\", \"title\": \"A Cleaner, Brighter Tomorrow\"}], \"button_link\": \"#milestones\", \"button_text\": \"Explore Our History\", \"impact_desc\": \"Our solutions are creating measurable change — improving health, enhancing productivity and building more sustainable communities across the globe.\", \"quote_brand\": \"CLEANER AIR\\nBRIGHTER SPACES\\nA HEALTHIER TOMORROW\", \"impact_badge\": \"CLEANER AIR\\nBRIGHTER SPACES\\nA HEALTHIER TOMORROW\", \"impact_image\": \"themes/default/assets/img/apartments.jpg\", \"impact_title\": \"A Healthier World Through Cleaner Air\"}', NULL, 1, '2026-10-06 04:20:13', '2026-10-07 00:36:35'),
(18, 'about_leadership', '{\"quote\": \"Great things happen when passionate people work together for a cleaner, healthier world.\", \"title\": \"Leadership\", \"number\": 3, \"members\": [{\"bio\": \"Leading AIRE\'s global vision for cleaner air and healthier lives.\", \"name\": \"Dr. James Liu\", \"role\": \"Chief Executive Officer\", \"image\": \"\"}, {\"bio\": \"Driving innovation in air purification and sustainable technologies.\", \"name\": \"Sarah Mitchell\", \"role\": \"Chief Technology Officer\", \"image\": \"\"}, {\"bio\": \"Scaling solutions globally with operational excellence and partnerships.\", \"name\": \"Kenji Tanaka\", \"role\": \"Chief Operations Officer\", \"image\": \"\"}, {\"bio\": \"Championing a healthier planet through people, partnerships and purpose.\", \"name\": \"Elena Rodriguez\", \"role\": \"Chief Sustainability Officer\", \"image\": \"\"}], \"subtitle\": \"Meet the people driving innovation and impact.\", \"banner_desc\": \"Our leadership team brings together decades of experience, a passion for cleaner air and a shared commitment to creating healthier spaces for everyone, everywhere.\", \"quote_brand\": \"CLEANER AIR\\nBRIGHTER SPACES\\nA HEALTHIER TOMORROW\", \"banner_badge\": \"OUR LEADERSHIP\", \"banner_image\": \"themes/default/assets/img/about/leadership.jpg\", \"banner_title\": \"People with Purpose\", \"team_heading\": \"Meet Our Leadership Team\", \"team_subheading\": \"A diverse group of visionaries, innovators and changemakers working together to build a cleaner, healthier future.\", \"banner_badge_text\": \"CLEANER AIR\\nBRIGHTER SPACES\\nA HEALTHIER TOMORROW\"}', NULL, NULL, '2026-10-06 04:20:13', '2026-10-06 04:20:13'),
(19, 'about_innovation', '{\"items\": [{\"desc\": \"Proprietary innovations in ionization, filtration, and acoustic airflow design.\", \"icon\": \"bi bi-patch-check\", \"title\": \"200+ Global Patents\"}, {\"desc\": \"AI-powered sensors that dynamically adjust filtration based on environmental metrics.\", \"icon\": \"bi bi-sliders\", \"title\": \"Smart Air Calibration\"}], \"title\": \"Innovation & Patents\", \"number\": 4, \"subtitle\": \"Pioneering technologies protected worldwide.\"}', NULL, NULL, '2026-10-06 04:20:13', '2026-10-06 04:20:13'),
(20, 'about_quality', '{\"items\": [{\"desc\": \"Rigorous international standards for manufacturing and environmental stewardship. \", \"icon\": \"bi bi-award\", \"title\": \"ISO 9001 & 14001\"}, {\"desc\": \"Independently lab tested and verified Clean Air Delivery Rates. \", \"icon\": \"bi bi-shield-lock\", \"title\": \"AHAM CADR Certified \"}], \"title\": \"Quality & Certifications \", \"number\": 5, \"subtitle\": \"Globally certified for safety, quality and performance.\"}', NULL, 1, '2026-10-06 04:20:13', '2026-10-07 00:42:44'),
(21, 'about_careers', '{\"title\": \"Careers \", \"number\": 6, \"subtitle\": \"Join our team and help shape a healthier world. \", \"card_desc\": \"We are always looking for passionate engineers, designers, scientists, and problem-solvers to join our global family.\", \"card_title\": \"Build the Future of Clean Air\", \"button_link\": \"/contact-us\", \"button_text\": \"View Open Positions\"}', NULL, 1, '2026-10-06 04:20:13', '2026-10-07 00:40:09'),
(22, 'about_news', '{\"title\": \"News & Media\", \"number\": 7, \"subtitle\": \"Latest news, press releases and media coverage.\", \"banner_desc\": \"Stay informed with our latest announcements, product innovations, and global milestones.\", \"button_link\": \"/contact-us\", \"button_text\": \"Media Inquiries\", \"banner_title\": \"Official Press & Media Center\"}', NULL, NULL, '2026-10-06 04:20:13', '2026-10-06 04:20:13'),
(23, 'about_global', '{\"items\": [{\"desc\": \"Regional hubs in North America, Europe, Asia Pacific, and the Middle East.\", \"icon\": \"bi bi-geo-alt\", \"title\": \"Global Offices\"}, {\"desc\": \"Direct fulfillment and certified maintenance partners across 100+ nations.\", \"icon\": \"bi bi-truck\", \"title\": \"Worldwide Distribution\"}], \"title\": \"Global Presence\", \"number\": 8, \"subtitle\": \"Serving customers in over 100 countries.\"}', NULL, NULL, '2026-10-06 04:20:13', '2026-10-06 04:20:13'),
